/** Turn a note like "Taobao 购物" into a short ASCII prefix: "taobao". */
export function slugify(note) {
  return String(note || "")
    .toLowerCase()
    .normalize("NFKD")
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-+|-+$/g, "")
    .slice(0, 20)
    .replace(/-+$/g, "");
}

